using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using static SvdGenerator.Naming;

namespace SvdGenerator
{
    /// <summary>
    /// Turns the device model into the text of the generated headers. Nothing is
    /// written to disk here: the result maps each file name to its content, with
    /// LF line endings whatever the platform.
    /// </summary>
    public static class Emitter
    {
        /// <summary>First characters of every generated file; how the generator recognises its own output.</summary>
        public const string BannerStart = "// Generated by SvdGenerator";

        const string InterruptsFile = "interrupts.hpp";
        const string DeviceFile = "device.hpp";
        const string VectorsFile = "vectors.hpp";

        /// <summary>The header of the register building blocks, written next to the others.</summary>
        public const string RegistersFile = "mmio.hpp";

        public static SortedDictionary<string, string> Emit(Device device, string generatorVersion)
        {
            var files = new SortedDictionary<string, string>(StringComparer.Ordinal);
            var banner = Banner(device, generatorVersion);
            var ns = Namespace(device.Name);

            files[InterruptsFile] = Normalize(new StringBuilder(banner).Append(Interrupts(device, ns)));
            files[DeviceFile] = Normalize(new StringBuilder(banner).Append(DeviceDescription(device, ns)));
            files[RegistersFile] = Normalize(new StringBuilder(RegistersBanner(generatorVersion)).Append(Registers()));
            if (Vectors(device, ns) is { } vectors)
                files[VectorsFile] = Normalize(new StringBuilder(banner).Append(vectors));

            // One header per group of peripherals: the SVD's groupName, or what
            // the names of the peripherals have in common (see Structure).
            foreach (var group in Structure.Build(device).GroupBy(t => PeripheralFile(t.FileKey), StringComparer.Ordinal))
            {
                var sb = new StringBuilder();
                sb.Append(banner);
                AppendLines(sb, "#pragma once", "", $"#include \"{RegistersFile}\"", "", $"namespace {ns}", "{", "");

                var types = group.ToList();
                foreach (var type in types)
                    sb.Append(TypeDefinition(type));

                foreach (var type in types)
                    foreach (var instance in type.Instances)
                        AppendLines(sb, $"inline {type.ClassName}& {Member(instance.Name)} = *reinterpret_cast<{type.ClassName}*>({Hex(instance.BaseAddress)});");

                foreach (var type in types)
                    sb.Append(InstanceResets(type));

                AppendLines(sb, "", $"}} // {ns}", "");

                files[group.Key] = Normalize(sb);
            }

            return files;
        }

        // The name of a peripheral header; never one of the headers the
        // generator writes for the device itself.
        static string PeripheralFile(string key)
        {
            var file = FileName(key);
            return file is InterruptsFile or DeviceFile or RegistersFile or VectorsFile ? FileName(key + "_2") : file;
        }

        // The register building blocks (namespace mmio) are a C++ file of this
        // repository, embedded in the generator and written as it is: the
        // generated headers depend on nothing but the standard library.
        static string Registers()
        {
            using var stream = typeof(Emitter).Assembly.GetManifestResourceStream(RegistersFile)
                ?? throw new InvalidOperationException($"{RegistersFile} is not embedded in the generator");
            using var reader = new System.IO.StreamReader(stream, Encoding.UTF8);
            return reader.ReadToEnd();
        }

        // This file does not derive from the SVD: it carries its own license
        // (in its header comment), not the notice of the SVD, and it is the
        // same for every device.
        static string RegistersBanner(string generatorVersion) =>
            $"{BannerStart} {generatorVersion}; do not edit.\n\n";

        static string Normalize(StringBuilder sb) => sb.ToString().Replace("\r\n", "\n");

        static void AppendLines(StringBuilder sb, params string[] lines)
        {
            foreach (var line in lines)
                sb.Append(line).Append('\n');
        }

        static string Banner(Device device, string generatorVersion)
        {
            var sb = new StringBuilder();
            var version = string.IsNullOrEmpty(device.Version) ? string.Empty : $", version {device.Version}";
            AppendLines(sb,
                $"{BannerStart} {generatorVersion}; do not edit.",
                $"// Source: {device.SourceFile} (device {device.Name}{version})",
                $"// SHA-256: {device.SourceSha256}");

            if (device.Notice.Count > 0)
            {
                AppendLines(sb, "//", "// Notice carried by the source file:", "//");
                foreach (var line in device.Notice)
                    AppendLines(sb, line.Length == 0 ? "//" : $"//   {line}");
            }

            AppendLines(sb, "");
            return sb.ToString();
        }

        static string Interrupts(Device device, string ns)
        {
            // Dedupe: an SVD can list the same IRQ on every peripheral that
            // shares it (e.g. TIM1_UP_TIM10_IRQn appears on TIM1 and TIM10),
            // and some SVDs even repeat an entry on a single peripheral with
            // slightly different descriptions (FPU). One enumerator per
            // (name, value) is what the C++ enum needs.
            var interrupts = device.Peripherals
                .SelectMany(p => p.Interrupts)
                .GroupBy(i => (i.Name, i.Value))
                .Select(g => g.First())
                .OrderBy(i => i.Value)
                .ThenBy(i => i.Name, StringComparer.Ordinal)
                .ToArray();

            var irqMaxSize = interrupts.Select(i => i.Name.Length).DefaultIfEmpty(0).Max();
            var commentMaxSize = interrupts.Select(i => OneLine(i.Description).Length).DefaultIfEmpty(0).Max();
            var irqCount = interrupts.Select(i => i.Value + 1).DefaultIfEmpty(0).Max();

            var sb = new StringBuilder();
            AppendLines(sb, "#pragma once", "", "#include <cstddef>", "#include <cstdint>", "", $"namespace {ns}", "{", "",
                "/** Number of entries the device interrupts take in the vector table. */",
                $"inline constexpr std::size_t irq_count = {irqCount};", "",
                "/** Device interrupts; the enumerators convert to their number. */",
                "enum IRQn_Type : std::uint16_t", "{");

            foreach (var interrupt in interrupts)
                AppendLines(sb, $"\t{Irq(interrupt.Name).PadRight(irqMaxSize + 10)} = {interrupt.Value,-5}, /** {OneLine(interrupt.Description).PadRight(commentMaxSize)} */");

            AppendLines(sb, "};", "", $"}} // {ns}");
            return sb.ToString();
        }

        static string DeviceDescription(Device device, string ns)
        {
            static string Text(string value) => "\"" + value.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";

            var sb = new StringBuilder();
            AppendLines(sb, "#pragma once", "", $"namespace {ns}", "{", "",
                "/** Name of the device, as the SVD file gives it. */",
                $"inline constexpr char device_name[] = {Text(device.Name)};",
                "/** Version of the SVD file the headers were generated from. */",
                $"inline constexpr char device_version[] = {Text(device.Version)};");

            if (device.Cpu is { } cpu)
            {
                AppendLines(sb, "", "/** Processor core. */", $"inline constexpr char cpu_name[] = {Text(cpu.Name)};");
                if (cpu.Revision != null)
                    AppendLines(sb, $"inline constexpr char cpu_revision[] = {Text(cpu.Revision)};");
                if (cpu.NvicPriorityBits != null)
                    AppendLines(sb, "/** Number of priority bits the interrupt controller implements. */", $"inline constexpr unsigned nvic_priority_bits = {cpu.NvicPriorityBits};");
                if (cpu.HasMpu != null)
                    AppendLines(sb, $"inline constexpr bool has_mpu = {(cpu.HasMpu.Value ? "true" : "false")};");
                if (cpu.HasFpu != null)
                    AppendLines(sb, $"inline constexpr bool has_fpu = {(cpu.HasFpu.Value ? "true" : "false")};");
            }

            AppendLines(sb, "", $"}} // {ns}");
            return sb.ToString();
        }

        // ── Vector table ───────────────────────────────────────────────────

        /// <summary>
        /// The system exceptions a core has besides reset, with their exception
        /// number; null for a core that has no Cortex-M vector table.
        /// </summary>
        static (string Name, int Number)[]? SystemExceptions(Cpu? cpu)
        {
            var baseline = new[] { ("nmi", 2), ("hard_fault", 3), ("svcall", 11), ("pendsv", 14), ("systick", 15) };
            var mainline = new[] { ("mem_manage", 4), ("bus_fault", 5), ("usage_fault", 6), ("debug_monitor", 12) };
            var secure = new[] { ("secure_fault", 7) };

            (string, int)[] Sorted(params (string Name, int Number)[][] sets) =>
                sets.SelectMany(s => s).OrderBy(e => e.Number).ToArray();

            switch (cpu?.Name)
            {
                // Armv6-M and Armv8-M Baseline.
                case "CM0" or "CM0PLUS" or "CM0+" or "CM1" or "SC000" or "CM23" or "ARMV8MBL":
                    return Sorted(baseline);
                // Armv7-M.
                case "CM3" or "SC300" or "CM4" or "CM7":
                    return Sorted(baseline, mainline);
                // Cortex-A: another exception model altogether.
                case { } name when name.StartsWith("CA", StringComparison.Ordinal):
                    return null;
                // Armv8-M Mainline, and what the SVD does not tell: every slot
                // any Cortex-M has, so that nothing a core offers is refused.
                default:
                    return Sorted(baseline, mainline, secure);
            }
        }

        static string? Vectors(Device device, string ns)
        {
            var exceptions = SystemExceptions(device.Cpu);
            if (exceptions == null)
                return null;

            var core = device.Cpu == null ? "the SVD names no core: every Cortex-M system exception" : device.Cpu.Name;
            var width = exceptions.Max(e => e.Name.Length);

            var sb = new StringBuilder();
            AppendLines(sb, "#pragma once", "", "#include <array>", "#include <cstddef>", "#include <cstdint>", "", $"#include \"{InterruptsFile}\"", "",
                $"namespace {ns}", "{", "",
                "/** A handler of the vector table. */",
                "using isr_handler_t = void (*)();", "",
                $"/** System exceptions of the core ({core}); the enumerators are their exception numbers. */",
                "enum class exception : std::uint8_t", "{");
            foreach (var (name, number) in exceptions)
                AppendLines(sb, $"\t{name.PadRight(width)} = {number},");
            AppendLines(sb, "};", "",
                "/** Decoration of a vector_table that installs the handlers of the device interrupts as they are. */",
                "struct undecorated",
                "{",
                "\ttemplate<isr_handler_t Handler>",
                "\tstatic constexpr isr_handler_t wrap = Handler;",
                "};", "",
                "/**",
                " * Called when with<>() or install<>() is given a slot that already has a",
                " * handler; replace<>() and reinstall<>() are how to mean it.",
                " *",
                " * It is not constexpr, so on a table built at compile time the build stops",
                " * there and nothing has to be defined. It is only declared here: a program",
                " * that calls install<>() on a table in RAM defines it, to report the mistake",
                " * its own way (its assert, its fault handler). It must not return.",
                " *",
                " * One overload for a system exception, one for a device interrupt: each is",
                " * given the slot that was already taken.",
                " */",
                "[[noreturn]] void handler_already_installed(exception taken);",
                "[[noreturn]] void handler_already_installed(IRQn_Type taken);", "",
                "/**",
                " * The vector table of the device, built at compile time: the initial stack",
                " * pointer, the reset handler, the system exceptions of the core, then one",
                " * slot per device interrupt.",
                " *",
                " * @code",
                " * [[gnu::section(\".isr_vector\"), gnu::used]]",
                " * constexpr auto g_vectors = vector_table<Default_Handler>(&_estack, Reset_Handler)",
                " *     .with<exception::hard_fault, Fault_Handler>()",
                " *     .with<USART3_IRQn, uart_isr>();",
                " * @endcode",
                " *",
                " * @tparam Unhandled  the handler of every system exception and device interrupt",
                " *         that is given none; null by default. It is installed as it is, without",
                " *         the decoration. The slots the core reserves are always null.",
                " * @tparam Decoration what a device interrupt handler is wrapped in. A type with",
                " *         a member `template<isr_handler_t> static constexpr isr_handler_t wrap`,",
                " *         for a kernel or a tracer that wants to run code around every handler.",
                " *         System exceptions are never decorated.",
                " */",
                "template<isr_handler_t Unhandled = nullptr, typename Decoration = undecorated>",
                "class vector_table",
                "{",
                "public:",
                "",
                "\t/** The enumerations this table is indexed by, for generic code that only has its type. */",
                "\tusing exception_type = exception;",
                "\tusing irq_type = IRQn_Type;",
                "",
                "\t/**",
                "\t * @param end_of_stack what the core loads in the main stack pointer at reset",
                "\t * @param reset        the reset handler",
                "\t */",
                "\tconstexpr vector_table(std::uint32_t* end_of_stack, isr_handler_t reset) : end_of_stack_(end_of_stack)",
                "\t{",
                "\t\thandlers_.fill(Unhandled);");
            foreach (var number in Enumerable.Range(2, 14).Where(n => exceptions.All(e => e.Number != n)))
                AppendLines(sb, $"\t\thandlers_[{number - 1}] = nullptr; // exception {number}: reserved");
            AppendLines(sb,
                "\t\thandlers_[0] = reset;",
                "\t}",
                "",
                "\t/**",
                "\t * This table with the handler of a system exception, which must not have one",
                "\t * yet: installing over another handler is handler_already_installed().",
                "\t */",
                "\ttemplate<exception Exception, isr_handler_t Handler>",
                "\t[[nodiscard]] constexpr auto with() const -> vector_table",
                "\t{",
                "\t\treturn installed(Exception, Handler, false);",
                "\t}",
                "",
                "\t/**",
                "\t * This table with the handler of a device interrupt, wrapped by the decoration.",
                "\t * The interrupt must not have a handler yet.",
                "\t */",
                "\ttemplate<IRQn_Type Irq, isr_handler_t Handler>",
                "\t[[nodiscard]] constexpr auto with() const -> vector_table",
                "\t{",
                "\t\treturn installed(Irq, Decoration::template wrap<Handler>, false);",
                "\t}",
                "",
                "\t/** This table with the handler of a system exception, whatever handler it had. */",
                "\ttemplate<exception Exception, isr_handler_t Handler>",
                "\t[[nodiscard]] constexpr auto replace() const -> vector_table",
                "\t{",
                "\t\treturn installed(Exception, Handler, true);",
                "\t}",
                "",
                "\t/** This table with the handler of a device interrupt, wrapped by the decoration, whatever handler it had. */",
                "\ttemplate<IRQn_Type Irq, isr_handler_t Handler>",
                "\t[[nodiscard]] constexpr auto replace() const -> vector_table",
                "\t{",
                "\t\treturn installed(Irq, Decoration::template wrap<Handler>, true);",
                "\t}",
                "",
                "\t/**",
                "\t * In place, for a table that lives in RAM: installs the handler of a system",
                "\t * exception, which must not have one yet. One store, no copy of the table.",
                "\t */",
                "\ttemplate<exception Exception, isr_handler_t Handler>",
                "\tconstexpr void install()",
                "\t{",
                "\t\tput(Exception, Handler, false);",
                "\t}",
                "",
                "\t/** In place: installs the handler of a device interrupt, which must not have one yet. */",
                "\ttemplate<IRQn_Type Irq, isr_handler_t Handler>",
                "\tconstexpr void install()",
                "\t{",
                "\t\tput(Irq, Decoration::template wrap<Handler>, false);",
                "\t}",
                "",
                "\t/** In place: installs the handler of a system exception, whatever handler it had. */",
                "\ttemplate<exception Exception, isr_handler_t Handler>",
                "\tconstexpr void reinstall()",
                "\t{",
                "\t\tput(Exception, Handler, true);",
                "\t}",
                "",
                "\t/** In place: installs the handler of a device interrupt, whatever handler it had. */",
                "\ttemplate<IRQn_Type Irq, isr_handler_t Handler>",
                "\tconstexpr void reinstall()",
                "\t{",
                "\t\tput(Irq, Decoration::template wrap<Handler>, true);",
                "\t}",
                "",
                "\t/**",
                "\t * This table with what a library installs in it: with(install) is install(*this).",
                "\t * Lets a kernel place its own handlers without the generated code knowing it.",
                "\t */",
                "\t[[nodiscard]] constexpr auto with(auto&& install) const",
                "\t{",
                "\t\treturn install(*this);",
                "\t}",
                "",
                "\t/** The handler at an exception number: 1 is reset, 16 the first device interrupt. */",
                "\t[[nodiscard]] constexpr auto handler(std::size_t exception_number) const -> isr_handler_t",
                "\t{",
                "\t\treturn handlers_[exception_number - 1];",
                "\t}",
                "",
                "\t/** Entries before the first device interrupt: the stack pointer and exceptions 1 to 15. */",
                "\tstatic constexpr std::size_t system_exceptions = 16;",
                "",
                "private:",
                "",
                "\t// Where the handler of an exception or of an interrupt is in handlers_.",
                "\tstatic constexpr auto index_of(exception slot) -> std::size_t { return static_cast<std::size_t>(slot) - 1; }",
                "\tstatic constexpr auto index_of(IRQn_Type slot) -> std::size_t { return system_exceptions - 1 + slot; }",
                "",
                "\tconstexpr void put(auto slot, isr_handler_t installing, bool replacing)",
                "\t{",
                "\t\tif (!replacing && handlers_[index_of(slot)] != Unhandled)",
                "\t\t\thandler_already_installed(slot);",
                "\t\thandlers_[index_of(slot)] = installing;",
                "\t}",
                "",
                "\tconstexpr auto installed(auto slot, isr_handler_t installing, bool replacing) const -> vector_table",
                "\t{",
                "\t\tauto table = *this;",
                "\t\ttable.put(slot, installing, replacing);",
                "\t\treturn table;",
                "\t}",
                "",
                "\tstd::uint32_t* end_of_stack_;",
                "\tstd::array<isr_handler_t, system_exceptions - 1 + irq_count> handlers_{};",
                "};",
                "",
                "static_assert(sizeof(vector_table<>) == (vector_table<>::system_exceptions + irq_count) * sizeof(void*));",
                "",
                $"}} // {ns}");
            return sb.ToString();
        }

        // Reset values that are not the same for every peripheral of a type
        // cannot be a constant of the register class.
        static string InstanceResets(PeripheralType type)
        {
            var sb = new StringBuilder();
            foreach (var instance in type.Instances)
            {
                var resets = type.InstanceResets[instance];
                if (resets.Count == 0)
                    continue;

                AppendLines(sb, "", $"/** Reset values of {instance.Name}, for the registers that do not reset alike in every {type.ClassName}. */",
                    $"namespace {Stem(instance.Name)}_reset", "{");
                foreach (var (register, reset) in resets)
                    AppendLines(sb, $"inline constexpr {IntType(register.Size)} {Member(register.Name)} = {Hex(reset)};");
                AppendLines(sb, "}");
            }
            return sb.ToString();
        }

        // ── Fields ─────────────────────────────────────────────────────────

        // ST names its enumerated values after their number (B_0x3): as a C++
        // name that says nothing more than the number itself.
        static readonly Regex NumberAsName = new("^[A-Za-z]?_?(0[xX][0-9A-Fa-f]+|[0-9]+)$", RegexOptions.CultureInvariant);

        static readonly HashSet<string> FieldClassMembers = new(StringComparer.Ordinal) { "offset", "width", "range", "mask" };

        /// <summary>The values of a field that get a named constant, with the name of each.</summary>
        static List<(string Name, EnumValue Value)> NamedValues(Field field)
        {
            var named = new List<(string, EnumValue)>();
            var used = new HashSet<string>(StringComparer.Ordinal);
            foreach (var value in field.Values)
            {
                if (NumberAsName.IsMatch(value.Name))
                    continue;
                var name = Member(value.Name);
                if (FieldClassMembers.Contains(name))
                    name = "_" + name;
                if (used.Add(name))
                    named.Add((name, value));
            }
            return named;
        }

        static string FieldDefinition(Field field, string regClassName, string qualifiedRegister, List<string> after)
        {
            var sb = new StringBuilder();
            var className = FieldClass(field.Name);
            var width = field.Width;
            var offset = field.Offset;
            var named = NamedValues(field);

            sb.AppendLine($"/**");
            sb.AppendLine($" * {OneLine(field.Description)}");
            if (field.Values.Count > 0)
            {
                sb.AppendLine(" *");
                foreach (var value in field.Values)
                {
                    var name = named.FirstOrDefault(n => ReferenceEquals(n.Value, value)).Name;
                    var label = name == null ? string.Empty : $"{name}: ";
                    sb.AppendLine($" *   {Hex(value.Value)}  {label}{OneLine(value.Description)}".TrimEnd());
                }
            }
            sb.AppendLine($" */");
            sb.AppendLine($"class {className} {{");
            sb.AppendLine($"public:");

            sb.AppendLine($"\tstatic constexpr {OffsetType} offset = {offset};");
            sb.AppendLine($"\tstatic constexpr {WidthType} width = {width};");

            if (width != 1)
            {
                sb.AppendLine($"\tstatic constexpr {IntType(width)} range = static_cast<{IntType(width)}>({Ones(width)});");
                sb.AppendLine($"\tstatic constexpr {IntType(width + offset)} mask = static_cast<{IntType(width + offset)}>(static_cast<{ValueType(width + offset)}>(range) << offset);");
            }
            else
            {
                sb.AppendLine($"\tstatic constexpr {IntType(width + offset)} mask = static_cast<{IntType(width + offset)}>(1ULL << offset);");
            }

            // The named values are objects of the field's own type, so they go
            // wherever a field goes: reg = mode_f::fast | en_f(). A class cannot
            // define constants of itself in its body; they are declared here
            // and defined after the peripheral class.
            if (named.Count > 0)
            {
                sb.AppendLine();
                sb.AppendLine($"\tstatic const {className} {string.Join(", ", named.Select(n => n.Name))};");
                foreach (var (name, value) in named)
                {
                    var literal = width == 1 ? (value.Value != 0 ? "true" : "false") : Hex(value.Value);
                    after.Add($"inline constexpr {qualifiedRegister}::{className} {qualifiedRegister}::{className}::{name}{{{literal}}};");
                }
            }

            sb.AppendLine();
            var rangeCheck = IsExactType(width) ? "" : " & range";
            var defaultValue = width == 1 ? " = true" : "";
            var body = IsExactType(width) ? "{}" : "{ if (__builtin_constant_p(value) && value > range) mmio::detail::field_value_out_of_range(); }";
            sb.AppendLine($"\tconstexpr {className}({ValueType(width)} value{defaultValue}) : value_(value{rangeCheck}) {body}");
            sb.AppendLine($"\tconstexpr operator {ValueType(width)}() const {{return value_;}}");

            // A read-only field is read from a register value, never written
            // into one: it has no conversion to the register type, so it cannot
            // reach an assignment, a |= or a <<=.
            if (field.Access != Access.ReadOnly)
            {
                sb.AppendLine(width == 1
                    ? $"\tconstexpr operator {regClassName}() const {{return value_ ? mask : 0;}}"
                    : $"\tconstexpr operator {regClassName}() const {{return static_cast<{ValueType(width + offset)}>(static_cast<{ValueType(width + offset)}>(value_) << offset);}}");

                sb.AppendLine($"\tconstexpr operator mmio::clear_set<{regClassName}>() const {{return mmio::clear_set<{regClassName}>(mask, *this);}}");
                sb.AppendLine($"\tconstexpr auto operator|({regClassName} other) const -> {regClassName} {{ return static_cast<{regClassName}>(*this) | other.value_;}}");
                sb.AppendLine($"\tconstexpr auto operator||(mmio::clear_set<{regClassName}> other) const -> mmio::clear_set<{regClassName}> {{return mmio::clear_set<{regClassName}>({regClassName}(mask) | other.clear(), *this | other.set()); }}");
            }

            // Without this, `a | b` between two fields that do not combine falls
            // back to the built-in | on their values, and the resulting integer
            // converts to any register.
            sb.AppendLine(field.Access != Access.ReadOnly
                ? $"\ttemplate<typename T> requires (std::is_class_v<T> && !std::is_convertible_v<T, {regClassName}> && !std::is_same_v<T, mmio::atomic_tag>) void operator|(T) const = delete; // a field of another register, or a read-only field, is not part of this register's value"
                : $"\ttemplate<typename T> requires std::is_class_v<T> void operator|(T) const = delete; // a read-only field is not part of the value written to the register");

            sb.AppendLine();
            sb.AppendLine("private:");
            sb.AppendLine($"\t {ValueType(width)} value_;");

            sb.AppendLine("};");
            return sb.ToString();
        }

        // ── Registers ──────────────────────────────────────────────────────

        static string RegisterDefinition(Register register, string className, string qualified, string description, List<string> after)
        {
            var sb = new StringBuilder();
            var type = ValueType(register.Size);

            sb.AppendLine($"/**");
            sb.AppendLine($" * {OneLine(description)}");
            sb.AppendLine($" */");
            sb.AppendLine($"class {className} {{");
            sb.AppendLine($"public:");

            if (register.Fields.Count > 0)
            {
                foreach (var field in register.Fields)
                {
                    sb.AppendLine();
                    sb.Append(FieldDefinition(field, className, qualified, after));
                }

                sb.AppendLine();

                foreach (var field in register.Fields)
                {
                    var fieldClass = FieldClass(field.Name);
                    if (field.Width == 1)
                        sb.AppendLine($"\t[[nodiscard]] constexpr auto {Member(field.Name)}() const -> {fieldClass} {{return {fieldClass}((value_ & {fieldClass}::mask) != 0);}}");
                    else
                        sb.AppendLine($"\t[[nodiscard]] constexpr auto {Member(field.Name)}() const -> {fieldClass} {{return {fieldClass}(static_cast<{ValueType(field.Width)}>(value_ >> {fieldClass}::offset));}}");
                }
            }

            sb.AppendLine();
            sb.AppendLine($"\tconstexpr {className}({type} value) : value_(value) {{}}");
            sb.AppendLine($"\tconstexpr auto operator |({className} other) const -> {className} {{ return value_ | other.value_; }}");
            sb.AppendLine($"\tconstexpr auto operator &({className} other) const -> {className} {{ return value_ & other.value_; }}");
            sb.AppendLine($"\tconstexpr auto operator ^({className} other) const -> {className} {{ return value_ ^ other.value_; }}");
            sb.AppendLine($"\tconstexpr auto operator ~() const -> {className} {{ return ~value_; }}");
            sb.AppendLine($"\tconstexpr bool operator ==(const {className}&) const = default;");
            sb.AppendLine($"\tauto operator ||(mmio::atomic_tag) const = delete; // a register value is built with |; put || between the fields of a <<= to clear and set them");
            sb.AppendLine($"\t[[nodiscard]] constexpr auto value() const {{ return value_; }}");

            sb.AppendLine();

            if (register.Reset is { } reset)
                sb.AppendLine($"\tstatic constexpr {type} reset_value = {Binary(reset)}; // {reset} {Hex(reset)}");

            sb.AppendLine();
            sb.AppendLine("private:");
            sb.AppendLine($"\t{type} value_;");

            sb.AppendLine("};");
            return sb.ToString();
        }

        static bool IsEquivalent(Field a, Field b) =>
            a.Name == b.Name &&
            a.Width == b.Width &&
            a.Offset == b.Offset &&
            a.Access == b.Access &&
            a.Values.SequenceEqual(b.Values);

        // Two registers share one class when they have the same fields, size and
        // reset value (CCMR1, CCMR2 become ccmrx_r).
        static bool IsEquivalent(Register a, Register b) =>
            a.Fields.Count == b.Fields.Count &&
            a.Fields.Count != 0 &&
            b.Fields.All(f => a.Fields.Any(f2 => IsEquivalent(f2, f))) &&
            a.Size == b.Size &&
            a.Reset == b.Reset;

        // ── Peripherals and clusters ───────────────────────────────────────

        static string TypeDefinition(PeripheralType type)
        {
            var sb = new StringBuilder();
            var after = new List<string>();
            sb.Append(ClassDefinition(type.Members, type.ClassName, type.ClassName, type.Description, null, after));

            if (after.Count > 0)
            {
                sb.AppendLine();
                foreach (var line in after)
                    sb.AppendLine(line);
            }

            sb.AppendLine();
            return sb.ToString();
        }

        /// <summary>
        /// The class of a peripheral or of a cluster: the classes of its
        /// registers and clusters, then one data member per register or cluster,
        /// at the offset the SVD states. What must follow the outermost class
        /// (layout checks, definitions of named values) is appended to
        /// <paramref name="after"/>.
        /// </summary>
        static string ClassDefinition(IReadOnlyList<Member> unordered, string className, string qualified, string description, long? paddedSize, List<string> after)
        {
            var sb = new StringBuilder();
            var classNames = new Dictionary<Member, string>();
            // Each member's offsetof access path on the class: either a bare
            // name, or "_lane_N.name" when it sits inside a named lane struct.
            var accessPath = new Dictionary<Member, string>();
            var checks = new List<string>();

            sb.AppendLine($"/**");
            sb.AppendLine($" * {OneLine(description)}");
            sb.AppendLine($" */");
            sb.AppendLine($"class {className} {{");
            sb.AppendLine($"public:");

            // The same sorted list feeds register-class equivalence detection,
            // layout walking and the offsetof static_asserts so all three see
            // identical names.
            var members = unordered
                .OrderBy(m => m.Offset)
                .ThenByDescending(m => m.End)
                .ToList();

            var used = new HashSet<string>(StringComparer.Ordinal);

            var families = new List<List<Register>>();
            foreach (var register in members.OfType<Register>())
            {
                var family = families.FirstOrDefault(f => IsEquivalent(f[0], register));
                if (family != null) family.Add(register);
                else families.Add(new List<Register> { register });
            }

            foreach (var family in families)
            {
                var names = family.Select(r => RegisterClass(r.Name)).ToList();
                var name = CommonWithReplace(names, "x");

                if (name is null)
                    name = names[0];
                else
                {
                    // ccmrx may already be taken by another family of the same
                    // shape: widen the placeholder until it is free.
                    for (var n = 2; used.Contains(name) && n <= 8; n++)
                        name = CommonWithReplace(names, new string('x', n))!;
                }

                var unique = name;
                for (var n = 2; !used.Add(unique); n++)
                    unique = $"{name}{n}";

                var familyDescription = CommonWithReplace(family.Select(r => r.Description), "X") ?? family[0].Description;

                sb.AppendLine();
                sb.Append(RegisterDefinition(family[0], unique, $"{qualified}::{unique}", familyDescription, after));

                foreach (var register in family)
                    classNames.Add(register, unique);
            }

            foreach (var cluster in members.OfType<Cluster>())
            {
                var baseName = TypeName(cluster.Name, "_c");
                var unique = baseName;
                for (var n = 2; !used.Add(unique); n++)
                    unique = $"{baseName}{n}";
                classNames.Add(cluster, unique);

                sb.AppendLine();
                sb.Append(ClassDefinition(cluster.Members, unique, $"{qualified}::{unique}", cluster.Description, cluster.IsArray ? cluster.Stride : null, checks));
            }

            if (members.Count > 0)
                sb.AppendLine();

            // Walk the members as a sequence of "footprint groups": each group
            // is a maximal run of members whose byte spans transitively
            // overlap. Single-member groups lay out flat. Multi-member groups
            // become an anonymous union of lanes (interval coloring). A lane
            // that is a single member at the group's offset rides directly
            // inside the anonymous union (non-POD member is fine in an
            // anonymous union by standard C++); any other lane has to live in
            // a NAMED struct field (`struct { ... } _lane_N;`) because GCC's
            // anonymous-struct extension forbids non-POD members and
            // mmio::memory holds a std::atomic, so it is not POD.
            // Trade-off: byte/half aliases get accessed as
            // `peripheral._lane_N.fooN` instead of `peripheral.fooN`.
            long currentOffset = 0;
            var laneId = 0;

            foreach (var group in BuildFootprintGroups(members))
            {
                var groupStart = group[0].Offset;
                var groupEnd = group.Max(r => r.End);

                var leadingPadding = groupStart - currentOffset;
                if (leadingPadding > 0)
                    sb.AppendLine($"\tmmio::padding<{leadingPadding}> _p{currentOffset};");

                var lanes = PartitionLanes(group);

                if (lanes.Count == 1)
                {
                    foreach (var r in lanes[0]) accessPath[r] = Member(r.Name);
                    EmitLaneMembers(sb, lanes[0], groupStart, classNames, "\t");
                }
                else
                {
                    sb.AppendLine("\tunion {");
                    foreach (var lane in lanes)
                    {
                        var bare = lane.Count == 1 && lane[0].Offset == groupStart;
                        if (bare)
                        {
                            accessPath[lane[0]] = Member(lane[0].Name);
                            EmitLaneMembers(sb, lane, groupStart, classNames, "\t\t");
                        }
                        else
                        {
                            var laneName = $"_lane_{laneId++}";
                            foreach (var r in lane) accessPath[r] = $"{laneName}.{Member(r.Name)}";
                            sb.AppendLine("\t\tstruct {");
                            EmitLaneMembers(sb, lane, groupStart, classNames, "\t\t\t");
                            sb.AppendLine($"\t\t}} {laneName};");
                        }
                    }
                    sb.AppendLine("\t};");
                }

                currentOffset = groupEnd;
            }

            // An element of an array of clusters is as long as the distance to
            // the next element.
            if (paddedSize is { } size && size > currentOffset)
                sb.AppendLine($"\tmmio::padding<{size - currentOffset}> _p{currentOffset};");

            sb.AppendLine("};");

            if (members.Count > 0)
            {
                after.Add($"static_assert(std::is_standard_layout_v<{qualified}>);");
                foreach (var member in members)
                    after.Add($"static_assert(offsetof({qualified}, {accessPath[member]}) == {member.Offset});");
                if (paddedSize != null)
                    after.Add($"static_assert(sizeof({qualified}) == {paddedSize});");
            }
            after.AddRange(checks);

            return sb.ToString();
        }

        // Build maximal runs of members whose byte spans transitively overlap.
        // Input: members sorted by offset asc, then end desc.
        // Output: groups in offset-asc order; within a group, the same sort.
        static List<List<Member>> BuildFootprintGroups(List<Member> sorted)
        {
            var groups = new List<List<Member>>();
            long currentEnd = -1;
            foreach (var r in sorted)
            {
                if (groups.Count == 0 || r.Offset >= currentEnd)
                {
                    groups.Add(new List<Member> { r });
                    currentEnd = r.End;
                }
                else
                {
                    groups[^1].Add(r);
                    if (r.End > currentEnd) currentEnd = r.End;
                }
            }
            return groups;
        }

        // Greedy interval coloring on a single footprint group. With the input
        // sorted (offset asc, size desc) the largest member lands in lane 0,
        // halfword aliases collapse into lane 1, byte aliases into lane 2.
        static List<List<Member>> PartitionLanes(List<Member> group)
        {
            var lanes = new List<List<Member>>();
            var laneEnds = new List<long>();
            foreach (var r in group)
            {
                var idx = -1;
                for (var i = 0; i < laneEnds.Count; i++)
                {
                    if (laneEnds[i] <= r.Offset) { idx = i; break; }
                }
                if (idx == -1)
                {
                    idx = lanes.Count;
                    lanes.Add(new List<Member>());
                    laneEnds.Add(0);
                }
                lanes[idx].Add(r);
                laneEnds[idx] = r.End;
            }
            return lanes;
        }

        // Emit a sequence of members belonging to one lane, inserting padding
        // for any internal gap between consecutive members. Padding is named
        // by the byte offset where it starts; intra-lane paddings are scoped to
        // the lane's named struct so two lanes with padding at the same offset
        // do not collide at class scope.
        static void EmitLaneMembers(
            StringBuilder sb, List<Member> lane, long laneStart,
            Dictionary<Member, string> classNames, string indent)
        {
            var cursor = laneStart;
            foreach (var member in lane)
            {
                if (member.Offset > cursor)
                    sb.AppendLine($"{indent}mmio::padding<{member.Offset - cursor}> _p{cursor};");

                var extent = member.IsArray ? $"[{member.Count}]" : string.Empty;
                if (member is Register r)
                {
                    var template = r.Access switch
                    {
                        Access.ReadOnly => "mmio::read_only_memory",
                        Access.WriteOnly => "mmio::write_only_memory",
                        _ => "mmio::memory",
                    };
                    sb.AppendLine($"{indent}{template}<{ValueType(r.Size)},{classNames[r]}> {Member(r.Name)}{extent};");
                }
                else
                {
                    sb.AppendLine($"{indent}{classNames[member]} {Member(member.Name)}{extent};");
                }

                cursor = member.End;
            }
        }
    }
}
